export const AskCommon = Schema.Struct({ "id": Schema.String, "status": AskStatus, "waiting": Schema.Boolean.annotate({ "description": "Whether an agent is following this ask right now: waiting on its call, or polling it as a background task." }), "project": Schema.optionalKey(Schema.String), "client": Schema.optionalKey(Schema.String.annotate({ "description": "The MCP client that asked, such as `claude-code 2.1.0`." })), "raisedBy": Schema.optionalKey(Schema.suspend((): Schema.Codec<Actor> => Actor).annotate({ "description": "Whose agent asked: the person its credential belongs to, when the deployment knows." })), "thread": Schema.Array(Entry).annotate({ "description": "Every turn after the ask was opened, oldest first." }), "createdAt": Schema.String.annotate({ "format": "date-time" }), "updatedAt": Schema.String.annotate({ "format": "date-time" }), "closedAt": Schema.optionalKey(Schema.String.annotate({ "format": "date-time" })) }).annotate({ "description": "What every ask carries, whatever its kind.", "identifier": "AskCommon" })
export type Ask = QuestionAsk | ReviewAsk | BriefingAsk | UnknownAsk<AskStatus>
export const Ask = Schema.Union([QuestionAsk, ReviewAsk, BriefingAsk, unknownAsk(AskStatus)]).annotate({ "description": "Something an agent needs from a person: a short thread that ends with a reply.", "identifier": "Ask" })
export type AskEvent = { readonly "type": "ask.opened" | "ask.updated", readonly "ask": Ask }
export const AskEvent = Schema.Struct({ "type": Schema.Literals(["ask.opened", "ask.updated"]), "ask": Ask }).annotate({ "description": "An ask was opened, or changed: a new turn, a close, or an agent starting or stopping following it.", "identifier": "AskEvent" })
export type AskPage = { readonly "items": ReadonlyArray<Ask>, readonly "nextBefore"?: string }
export const AskPage = Schema.Struct({ "items": Schema.Array(Ask), "nextBefore": Schema.optionalKey(Schema.String.annotate({ "description": "Pass as `before` for the next page. Absent on the last page.", "format": "date-time" })) }).annotate({ "description": "A page of closed asks, newest first.", "identifier": "AskPage" })
export type Snapshot = { readonly "open": ReadonlyArray<Ask>, readonly "recent": ReadonlyArray<Ask> }
export const Snapshot = Schema.Struct({ "open": Schema.Array(Ask), "recent": Schema.Array(Ask) }).annotate({ "description": "Open asks, newest first, and the most recently closed.", "identifier": "Snapshot" })
export type SnapshotEvent = { readonly "type": "snapshot", readonly "snapshot": Snapshot }
export const SnapshotEvent = Schema.Struct({ "type": Schema.Literal("snapshot"), "snapshot": Snapshot }).annotate({ "description": "The first frame on the event socket, and the state to start from.", "identifier": "SnapshotEvent" })
export type ServerEvent = SnapshotEvent | AskEvent | UnknownEvent
export const ServerEvent = Schema.Union([SnapshotEvent, AskEvent, unknownEvent]).annotate({ "description": "A frame on the event socket.", "identifier": "ServerEvent" })
